      hookSentences: [
        "Looking for the direct link to apply for the UGC Ishan Uday Special Scholarship Scheme for the North Eastern Region?",
        "Submit your fresh registration or renewal application using the official National Scholarship Portal (NSP) link below securely."
      ],
      services: "Fresh Application, Renewal, Check Status",
