    as: {
      title: "\u09F0\u09C7\u099A\u09A8 \u0995\u09BE\u09F0\u09CD\u09A1\u09F0 \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u09B8\u09C7\u09F1\u09BE (\u0985\u09B8\u09AE)",
      hookSentences: [
        "\u09A8\u09A4\u09C1\u09A8 \u09F0\u09C7\u099A\u09A8 \u0995\u09BE\u09F0\u09CD\u09A1\u09F0 \u09AC\u09BE\u09AC\u09C7 \u0986\u09AC\u09C7\u09A6\u09A8 \u0995\u09F0\u09BF\u09AC, \u09B8\u09A6\u09B8\u09CD\u09AF \u09B8\u0982\u09AF\u09CB\u0997 \u0995\u09F0\u09BF\u09AC \u09AC\u09BE \u0986\u09A7\u09BE\u09F0 \u09B2\u09BF\u0982\u0995 \u0995\u09F0\u09BF\u09AC \u09AC\u09BF\u099A\u09BE\u09F0\u09C7 \u09A8\u09C7\u0995\u09BF?",
        "\u0996\u09BE\u09A6\u09CD\u09AF \u0986\u09F0\u09C1 \u0985\u09B8\u09BE\u09AE\u09F0\u09BF\u0995 \u09AF\u09CB\u0997\u09BE\u09A8 \u09AC\u09BF\u09AD\u09BE\u0997\u09F0 \u09F1\u09C7\u09AC\u099B\u09BE\u0987\u099F\u09F0 \u099C\u09F0\u09BF\u09AF\u09BC\u09A4\u09C7 \u098F\u0987 \u09B8\u09C7\u09F1\u09BE\u09B8\u09AE\u09C2\u09B9 \u0986\u09F0\u09C1 \u09B9\u09BF\u09A4\u09BE\u09A7\u09BF\u0995\u09BE\u09F0\u09C0\u09F0 \u09A4\u09BE\u09B2\u09BF\u0995\u09BE \u09B2\u09BE\u09AD \u0995\u09F0\u0995\u0964"
      ],
      services: "\u09A8\u09A4\u09C1\u09A8 \u09F0\u09C7\u099A\u09A8 \u0995\u09BE\u09F0\u09CD\u09A1, \u09B8\u09A6\u09B8\u09CD\u09AF \u09B8\u0982\u09AF\u09CB\u099C\u09A8, \u0986\u09A7\u09BE\u09F0 \u09B8\u0982\u09AF\u09CB\u0997, \u0987-\u0995\u09C7\u09F1\u09BE\u0987\u099A\u09BF (e-KYC)",
      checklist: [
        "\u09A8\u09A4\u09C1\u09A8 \u0995\u09BE\u09F0\u09CD\u09A1\u09F0 \u09AC\u09BE\u09AC\u09C7 \u09AA\u09F0\u09BF\u09AF\u09BC\u09BE\u09B2\u09F0 \u0989\u09AA\u09BE\u09F0\u09CD\u099C\u09A8\u09F0 \u099A\u09F0\u09CD\u09A4 \u09AA\u09C2\u09F0\u09A3 \u0995\u09F0\u09BF\u09AC \u09B2\u09BE\u0997\u09BF\u09AC \u0986\u09F0\u09C1 \u0986\u09A7\u09BE\u09F0 \u0995\u09BE\u09F0\u09CD\u09A1 \u09A5\u09BE\u0995\u09BF\u09AC \u09B2\u09BE\u0997\u09BF\u09AC\u0964",
        "\u09A8\u09BE\u09AE \u09AD\u09C1\u09B2 \u09B8\u0982\u09B6\u09CB\u09A7\u09A8 \u09AC\u09BE \u09A8\u09A4\u09C1\u09A8 \u09A8\u09BE\u09AE \u09AD\u09F0\u09CD\u09A4\u09BF \u0995\u09F0\u09BF\u09AC\u09B2\u09C8 \u09B8\u09C7\u09F1\u09BE \u09B8\u09C7\u09A4\u09C1 (Sewa Setu) \u09AA\u09F0\u09CD\u099F\u09C7\u09B2 \u09AC\u09CD\u09AF\u09F1\u09B9\u09BE\u09F0 \u0995\u09F0\u0995\u0964",
        "\u0987-\u0995\u09C7\u09F1\u09BE\u0987\u099A\u09BF\u09F0 (e-KYC) \u09AC\u09BE\u09AC\u09C7 \u0986\u09AA\u09CB\u09A8\u09BE\u09F0 \u0993\u099A\u09F0\u09F0 \u09B8\u09C1\u09B2\u09AD \u09AE\u09C2\u09B2\u09CD\u09AF\u09F0 \u09A6\u09CB\u0995\u09BE\u09A8\u09A4 \u0996\u09AC\u09F0 \u0995\u09F0\u0995\u0964",
        "PDS \u09AA\u09F0\u09CD\u099F\u09C7\u09B2\u09F0 \u099C\u09F0\u09BF\u09AF\u09BC\u09A4\u09C7 \u0997\u09BE\u0981\u0993 \u0985\u09A8\u09C1\u09B8\u09F0\u09BF \u09B9\u09BF\u09A4\u09BE\u09A7\u09BF\u0995\u09BE\u09F0\u09C0\u09F0 \u09A4\u09BE\u09B2\u09BF\u0995\u09BE\u0996\u09A8 \u099A\u09BE\u09AC \u09AA\u09BE\u09F0\u09BF\u09AC\u0964"
      ],
      ctaText: "\u{1F449} \u0996\u09BE\u09A6\u09CD\u09AF \u09AF\u09CB\u0997\u09BE\u09A8 \u09AC\u09BF\u09AD\u09BE\u0997\u09F0 \u09AA\u09F0\u09CD\u099F\u09C7\u09B2\u09B2\u09C8 \u09AF\u09BE\u0993\u0995",
      faqs: [
        {
          question: "\u09A8\u09A4\u09C1\u09A8 \u09B8\u09A6\u09B8\u09CD\u09AF\u09F0 \u09A8\u09BE\u09AE \u0995\u09C7\u09A8\u09C7\u0995\u09C8 \u09AD\u09F0\u09CD\u09A4\u09BF \u0995\u09F0\u09BF\u09AE?",
          answer: '\u09B8\u09C7\u09F1\u09BE \u09B8\u09C7\u09A4\u09C1 \u09AA\u09F0\u09CD\u099F\u09C7\u09B2\u09A4 \u0997\u09C8 "Addition of Family Member" \u09A4 \u0986\u09A7\u09BE\u09F0 \u0986\u09F0\u09C1 \u099C\u09A8\u09CD\u09AE\u09F0 \u09AA\u09CD\u09F0\u09AE\u09BE\u09A3\u09AA\u09A4\u09CD\u09F0 \u09A6\u09BF \u0985\u09A8\u09B2\u09BE\u0987\u09A8 \u0986\u09AC\u09C7\u09A6\u09A8 \u0995\u09F0\u09BF\u09AC \u09AA\u09BE\u09F0\u09C7\u0964'
        },
        {
          question: "e-KYC \u0995\u09BF\u09AF\u09BC \u099C\u09F0\u09C1\u09F0\u09C0?",
          answer: "\u099A\u09F0\u0995\u09BE\u09F0\u09C0 \u09F0\u09C7\u099A\u09A8 \u0986\u09F0\u09C1 \u0986\u09AF\u09BC\u09C1\u09B7\u09CD\u09AE\u09BE\u09A8 \u0985\u09B8\u09AE\u09F0 \u09A8\u09BF\u099A\u09BF\u09A8\u09BE \u09AC\u09BF\u09A8\u09BE\u09AE\u09C2\u09B2\u09C0\u09AF\u09BC\u09BE \u099A\u09BF\u0995\u09BF\u09CE\u09B8\u09BE \u09B8\u09C1\u09AC\u09BF\u09A7\u09BE \u0985\u09AC\u09CD\u09AF\u09BE\u09B9\u09A4 \u09F0\u09BE\u0996\u09BF\u09AC\u09B2\u09C8 \u09AA\u09F0\u09BF\u09AF\u09BC\u09BE\u09B2\u09F0 \u09B8\u0995\u09B2\u09CB\u09F0\u09C7 e-KYC \u09AC\u09BE\u09A7\u09CD\u09AF\u09A4\u09BE\u09AE\u09C2\u09B2\u0995\u0964"
        }
      ]
    }
